  std::string filename;
  std::getline(std::cin, filename);

  std::ifstream infile(filename);
  if (infile.is_open()) {
    std::string line;
    int word_count = 0;

    while (getline(infile, line)) {
      std::istringstream iss(line);

      while (iss >> line) {
